  centre=[("v(t) = (1/V)·dx/dt", "v égale un sur V fois d x sur d t"), ("v diminue : vrai", "la vitesse diminue au cours du temps: vrai"),
          ("v(3 min) = 1,6 mmol·L⁻¹·min⁻¹", "le résultat: v égale un virgule six")],
